CREATE TABLE app_user(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(10) NOT NULL);
CREATE TABLE product(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(150) NOT NULL,category VARCHAR(60) NOT NULL,description VARCHAR(2000) NOT NULL,price NUMERIC(15,0) NOT NULL CHECK(price>0),stock INTEGER NOT NULL CHECK(stock>=0),active BOOLEAN NOT NULL);
CREATE TABLE shop_order(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES app_user(id),recipient VARCHAR(100) NOT NULL,phone VARCHAR(20) NOT NULL,address VARCHAR(500) NOT NULL,total NUMERIC(15,0) NOT NULL,status VARCHAR(20) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE order_item(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES shop_order(id),product_id BIGINT NOT NULL REFERENCES product(id),product_name VARCHAR(150) NOT NULL,unit_price NUMERIC(15,0) NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0));
